def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==8 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]!=8:
              seen.add(q); stack.append(q)
        colored=[(y,x) for y,x in comp if grid[y][x] not in (0,8)]
        if not colored: continue
        r0=min(y for y,x in colored); r1=max(y for y,x in colored)
        c0=min(x for y,x in colored); c1=max(x for y,x in colored)
        th,tw=r1-r0+1,c1-c0+1
        tile=[[grid[y][x] for x in range(c0,c1+1)] for y in range(r0,r1+1)]
        for y,x in comp: out[y][x]=tile[(y-r0)%th][(x-c0)%tw]
    return out

